**Modular Enterprise E-Commerce Checkout Orchestrator in C#**
===========================================================

### Overview

The following is a high-level implementation of a modular e-commerce checkout orchestrator in C#. The system consists of three primary components:

1.  **Shopping Cart Validation Engine**: Responsible for verifying item availability and pricing.
2.  **Saga Transaction Coordinator**: Orchestrates transactions across microservices, including inventory, payment, and shipping, with compensating rollbacks.
3.  **Invoice Generator**: Formats PDF billing statements.

### Shopping Cart Validation Engine
----------------------------------

```csharp
// Shopping Cart Validation Engine
public interface IShoppingCartValidator
{
    bool ValidateShoppingCart(ShoppingCart cart);
}

public class ShoppingCartValidator : IShoppingCartValidator
{
    private readonly IProductRepository _productRepository;

    public ShoppingCartValidator(IProductRepository productRepository)
    {
        _productRepository = productRepository;
    }

    public bool ValidateShoppingCart(ShoppingCart cart)
    {
        foreach (var item in cart.Items)
        {
            var product = _productRepository.GetProduct(item.ProductId);
            if (product == null || product.Quantity < item.Quantity)
            {
                return false; // Insufficient quantity or product not found
            }
            if (product.Price != item.Price)
            {
                return false; // Price mismatch
            }
        }
        return true; // Shopping cart is valid
    }
}

public class ShoppingCart
{
    public List<ShoppingCartItem> Items { get; set; }
}

public class ShoppingCartItem
{
    public int ProductId { get; set; }
    public int Quantity { get; set; }
    public decimal Price { get; set; }
}
```

### Saga Transaction Coordinator
---------------------------------

```csharp
// Saga Transaction Coordinator
public interface ISagaTransactionCoordinator
{
    void ProcessTransaction(ShoppingCart cart);
}

public class SagaTransactionCoordinator : ISagaTransactionCoordinator
{
    private readonly IInventoryService _inventoryService;
    private readonly IPaymentService _paymentService;
    private readonly IShippingService _shippingService;

    public SagaTransactionCoordinator(IInventoryService inventoryService, IPaymentService paymentService, IShippingService shippingService)
    {
        _inventoryService = inventoryService;
        _paymentService = paymentService;
        _shippingService = shippingService;
    }

    public void ProcessTransaction(ShoppingCart cart)
    {
        try
        {
            // Reserve inventory
            _inventoryService.ReserveInventory(cart);

            // Process payment
            _paymentService.ProcessPayment(cart);

            // Ship order
            _shippingService.ShipOrder(cart);

            // Commit transaction
            _inventoryService.CommitInventory();
            _paymentService.CommitPayment();
            _shippingService.CommitShipment();
        }
        catch (Exception ex)
        {
            // Rollback transaction
            _inventoryService.RollbackInventory();
            _paymentService.RollbackPayment();
            _shippingService.RollbackShipment();
            throw; // Rethrow the exception
        }
    }
}

// Microservice interfaces
