### Example Usage
-----------------

```csharp
class Program
{
    static void Main(string[] args)
    {
        // Create a shopping cart
        var cart = new ShoppingCart
        {
            Items = new List<ShoppingCartItem>
            {
                new ShoppingCartItem { ProductId = 1, Quantity = 2, Price = 10.99m },
                new ShoppingCartItem { ProductId = 2, Quantity = 1, Price = 5.99m }
            }
        };

        // Validate the shopping cart
        var validator = new ShoppingCartValidator(new ProductRepository());
        if (validator.ValidateShoppingCart(cart))
        {
            Console.WriteLine("Shopping cart is valid.");

            // Process the transaction
            var coordinator = new SagaTransactionCoordinator(new InventoryService(), new PaymentService(), new ShippingService());
            coordinator.ProcessTransaction(cart);

            // Generate the invoice
            var generator = new InvoiceGenerator();
            generator.GenerateInvoice(cart);
        }
        else
        {
            Console.WriteLine("Shopping cart is not valid.");
        }
    }
}

